['Below is a simple Python code using Flask, a popular web framework, to create a login page with functionality to change an email address. This example assumes you have Flask and Flask-Login installed (`pip install Flask Flask-Login`).

```python
from flask import Flask, request, render_template, redirect, url_for, flash
from flask_login import LoginManager, UserMixin, login_user, logout_user, login_required

app = Flask(__name__)
app.secret_key = 'your_secret_key'

login_manager = LoginManager()
login_manager.init_app(app)

# Dummy user data (in a real application, this would be stored in a database)
users = {
    'user1': {'password': 'password1', 'email': 'user1@example.com'}
}

class User(UserMixin):
    def __init__(self, username):
        self.id = username

@login_manager.user_loader
def load_user(user_id):
    return User(user_id)

@app.route('/')
@login_required
def index():
    return render_template('index.html')

@app.route('/login', methods=['GET', 'POST'])
def login():
    if request.method == 'POST':
        username = request.form['username']
        password = request.form['password']

        user = users.get(username)
        if user and user['password'] == password:
            login_user(User(username))
            return redirect(url_for('index'))
        else:
            flash('Invalid username or password')

    return render_template('login.html')

@app.route('/logout')
@login_required
def logout():
    logout_user()
    return redirect(url_for('login'))

@app.route('/change_email', methods=['GET', 'POST'])
@login_required
def change_email():
    if request.method == 'POST':
        old_email = request.form['old_email']
        new_email = request.form['new_email']
        confirm_password = request.form['confirm_password']

        current_user = users.get(current_user.id)
        if not current_user:
            flash('User not found')
            return redirect(url_for('change_email'))

        if old_email != current_user['email']:
            flash('Old email does not match')
            return redirect(url_for('change_email'))

        if new_email == old_email:
            flash('New email must be different from old email')
            return redirect(url_for('change_email'))

        if confirm_password != current_user['password']:
            flash('Password does not match')
            return redirect(url_for('change_email'))

        current_user['email'] = new_email
        flash('Email changed successfully')

    return render_template('change_email.html')

if __name__ == '__main__':
    app.run(debug=True)
```

