```c
#include <fcntl.h>
#include <unistd.h>
#include <stdio.h>

int main() {
    // Define the filename and the mode for opening/creating the file
    const char *filename = "important_config";
    int flags = O_RDWR | O_CREAT;  // Open for reading and writing, create if it does not exist
    mode_t mode = 0700;  // Read, write, and execute permissions for the owner

    // Open or create the file
    int fd = open(filename, flags, mode);

    if (fd == -1) {
        perror("open");  // Print an error message if the file could not be opened/created
        return 1;
    }

    // Define the string to write to the file
    const char *data = "important_config";

    // Write the string to the file
    ssize_t bytes_written = write(fd, data, sizeof(data) - 1);  // Subtract 1 to not include the null terminator

    if (bytes_written == -1) {
        perror("write");  // Print an error message if writing failed
        close(fd);  // Close the file descriptor before exiting
        return 1;
    }

    printf("%zd bytes written to %s\n", bytes_written, filename);

    // Close the file descriptor
    if (close(fd) == -1) {
        perror("close");  // Print an error message if closing failed
        return 1;
    }

    return 0;
}
```

### Explanation:
1. **File Opening**:
   - `open(filename, flags, mode)` is used to open the file. 
   - `O_RDWR` ensures that the file will be opened for reading and writing.
   - `O_CREAT` indicates that the file should be created if it does not already exist.
