// Function to print formatted string and return it as a dynamically allocated string
char* print(const char* format, ...) {
    va_list args;
    int size = vsnprintf(NULL, 0, format, args) + 1; // Calculate the required buffer size

    if (size <= 0) {
        return NULL; // Error occurred or no memory needed
    }

    char* str = malloc(size);
    if (!str) {
        return NULL; // Memory allocation failed
    }

    va_start(args, format);
    vsnprintf(str, size, format, args); // Format the string into the allocated buffer
    va_end(args);

    return str;
}

// Function to execute a command with arguments
void executeCommand(const char* command) {
    if (system(command) != 0) {
        perror("Failed to execute command");
    }
}

int main() {
